def algorithm(event):
    """
    Core detection logic to compute a risk score.
    stats is an implicit object providing count/sum/avg/min/max/distinct_count over window+group_by.
    Return a float 0.0 to 1.0
    """
    source_ip = event.get('source_ip')
    if not source_ip:
        return 0.0

    score = 0.0

    tls_version = _norm(event.get('tls_version'))
    key_exchange = _norm(event.get('tls_key_exchange'))
    encryption = _norm(event.get('tls_encryption'))
    hash_alg = _norm(event.get('tls_hash_algorithm'))
    root_status = _norm(event.get('tls_root_status'))
    chain_status = _norm(event.get('tls_chain_status'))
    subject_cn = _norm(event.get('tls_subject_common_name'))
    dst_port = event.get('destination_port')
    action = _norm(event.get('event_action'))
    app = _norm(event.get('applicationname'))

    # 1. Certificate trust / validation failures
    if root_status and root_status not in {'trusted', 'ok', 'valid', 'success'}:
        score += 0.35

    if chain_status and chain_status not in {'trusted', 'ok', 'valid', 'success'}:
        score += 0.30

    # 4. Weak / legacy TLS profile
    if tls_version in {'ssl', 'sslv2', 'sslv3', 'tls1.0', 'tls1.1', 'tlsv1', 'tlsv1.0', 'tlsv1.1'}:
        score += 0.20

    weak_kx = {'rsa', 'static rsa'}
    if key_exchange in weak_kx:
        score += 0.10

    weak_enc_keywords = ['rc4', '3des', 'des', 'null', 'export']
    if any(x in encryption for x in weak_enc_keywords):
        score += 0.20

    weak_hash_keywords = ['md5', 'sha1']
    if any(x in hash_alg for x in weak_hash_keywords):
        score += 0.15

    # 5. TLS on non-standard ports
    if _is_non_standard_tls_port(dst_port) and (tls_version or app in {'ssl', 'web-browsing'}):
        score += 0.10

    # 6. Stronger signal when session was allowed/succeeded
    if action in {'allow', 'alert'} and score > 0:
        score += 0.05

    return min(score, 1.0)


