def _cn_sni_mismatch(subject_cn, sni):
    subject_cn = _norm(subject_cn)
    sni = _norm(sni)

    if not subject_cn or not sni:
        return False

    if subject_cn == sni:
        return False

    # wildcard support
    if subject_cn.startswith('*.'):
        suffix = subject_cn[1:]  # ".example.com"
        if sni.endswith(suffix):
            return False

    return True
def _is_non_standard_tls_port(port):
    try:
        p = int(port)
    except Exception:
        return False
    return p not in {443, 8443, 9443}